import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { authAPI } from '../../utils/api';

const validators = {
  username: v => {
    if (!v) return '请输入用户名'
    if (v.length < 3 || v.length > 30) return '用户名需3-30个字符'
    if (!/^[a-zA-Z0-9_\u4e00-\u9fa5]+$/.test(v)) return '只能包含字母、数字、中文、下划线'
    return ''
  },
  password: v => {
    if (!v) return '请输入密码'
    if (v.length < 6 || v.length > 50) return '密码需6-50个字符'
    return ''
  },
  confirmPassword: (v, form) => {
    if (!v) return '请确认密码'
    if (v !== form.password) return '两次密码不一致'
    return ''
  },
  email: v => {
    if (!v) return ''
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v)) return '邮箱格式不正确'
    return ''
  },
  phone: v => {
    if (!v) return ''
    if (!/^1\d{10}$/.test(v)) return '手机号需11位数字'
    return ''
  },
  security_question: v => {
    if (!v) return '请输入安全问题'
    if (v.length < 2 || v.length > 200) return '安全问题需2-200个字符'
    return ''
  },
  security_answer: v => {
    if (!v) return '请输入安全答案'
    if (v.length < 2 || v.length > 200) return '安全答案需2-200个字符'
    return ''
  }
}

const Register = () => {
    const [form, setForm] = useState({
        username: '', password: '', confirmPassword: '',
        email: '', phone: '', security_question: '', security_answer: ''
    })
    const [errors, setErrors] = useState({})
    const [touched, setTouched] = useState({})
    const [serverError, setServerError] = useState('')
    const [success, setSuccess] = useState('')
    const [loading, setLoading] = useState(false)
    const navigate = useNavigate()

    const validate = (name, value) => {
        const fn = validators[name]
        if (!fn) return ''
        return fn(value, form)
    }

    const handleChange = (e) => {
        const { name, value } = e.target
        const newForm = { ...form, [name]: value }
        setForm(newForm)
        if (touched[name]) {
            setErrors(prev => ({ ...prev, [name]: validate(name, value) }))
        }
    }

    const handleBlur = (e) => {
        const { name, value } = e.target
        setTouched(prev => ({ ...prev, [name]: true }))
        setErrors(prev => ({ ...prev, [name]: validate(name, value) }))
    }

    const handleSubmit = async (e) => {
        e.preventDefault()
        setServerError('')
        setSuccess('')

        // 标记所有字段已触碰，显示全部错误
        const allTouched = {}
        const allErrors = {}
        for (const key of Object.keys(validators)) {
            allTouched[key] = true
            const err = validate(key, form[key])
            if (err) allErrors[key] = err
        }
        allTouched.confirmPassword = true
        const confirmErr = validators.confirmPassword(form.confirmPassword, form)
        if (confirmErr) allErrors.confirmPassword = confirmErr
        setTouched(allTouched)
        setErrors(allErrors)
        if (Object.keys(allErrors).length > 0) return

        setLoading(true)
        try {
            const res = await authAPI.register({
                username: form.username, password: form.password,
                email: form.email, phone: form.phone,
                security_question: form.security_question, security_answer: form.security_answer
            })
            if (res.code === 200) {
                setSuccess('注册成功！立即登录')
                setTimeout(() => navigate('/login'), 2000)
            } else {
                setServerError(res.msg || '注册失败')
            }
        } catch (err) {
            setServerError(err.response?.data?.msg || '网络错误，请稍后重试')
        } finally {
            setLoading(false)
        }
    }

    const fields = [
        { name: 'username', label: '用户名', type: 'text', required: true, placeholder: '3-30位字母、数字、中文、下划线' },
        { name: 'password', label: '密码', type: 'password', required: true, placeholder: '6-50个字符' },
        { name: 'confirmPassword', label: '确认密码', type: 'password', required: true, placeholder: '再次输入密码' },
        { name: 'email', label: '邮箱', type: 'email', required: false, placeholder: '选填' },
        { name: 'phone', label: '手机号', type: 'tel', required: false, placeholder: '选填，11位手机号' },
        { name: 'security_question', label: '安全问题', type: 'text', required: true, placeholder: '例如：您母亲的名字？' },
        { name: 'security_answer', label: '安全答案', type: 'text', required: true, placeholder: '2-200个字符' },
    ]

    return (
        <div style={styles.container}>
            <div style={styles.card}>
                <h2 style={styles.title}>注册</h2>
                <p style={styles.subtitle}>创建您的账号</p>
                {serverError && <div style={styles.error}>{serverError}</div>}
                {success && <div style={styles.success}>{success}</div>}
                <form onSubmit={handleSubmit} style={styles.form}>
                    {fields.map(f => (
                        <div key={f.name} style={styles.inputGroup}>
                            <label style={styles.label}>{f.label} {f.required && '*'}</label>
                            <input
                                type={f.type} name={f.name} placeholder={f.placeholder}
                                value={form[f.name]} onChange={handleChange} onBlur={handleBlur}
                                style={{
                                    ...styles.input,
                                    borderColor: touched[f.name] && errors[f.name] ? '#ff4d4f' : touched[f.name] && !errors[f.name] && form[f.name] ? '#52c41a' : '#ddd'
                                }}
                            />
                            {touched[f.name] && errors[f.name] && <span style={styles.fieldError}>{errors[f.name]}</span>}
                        </div>
                    ))}
                    <button type="submit" style={styles.button} disabled={loading}>
                        {loading ? '注册中...' : '注册'}
                    </button>
                </form>
                <div style={styles.links}>
                    <Link to="/login" style={styles.link}>已有账号？立即登录</Link>
                </div>
            </div>
        </div>
    )
}

const styles = {
    container: { minHeight: '100vh', display: 'flex', alignItems: 'center', justifyContent: 'center', background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)', padding: '20px' },
    card: { background: 'white', borderRadius: '10px', padding: '40px', width: '100%', maxWidth: '420px', boxShadow: '0 10px 40px rgba(0,0,0,0.2)' },
    title: { margin: '0 0 10px 0', fontSize: '24px', fontWeight: 'bold', color: '#333', textAlign: 'center' },
    subtitle: { margin: '0 0 30px 0', fontSize: '14px', color: '#666', textAlign: 'center' },
    error: { background: '#fee2e2', color: '#dc2626', padding: '10px', borderRadius: '5px', marginBottom: '20px', fontSize: '14px' },
    success: { background: '#d1fae5', color: '#059669', padding: '10px', borderRadius: '5px', marginBottom: '20px', fontSize: '14px' },
    form: { display: 'flex', flexDirection: 'column' },
    inputGroup: { marginBottom: '15px' },
    label: { display: 'block', marginBottom: '5px', fontSize: '14px', fontWeight: '500', color: '#333' },
    input: { width: '100%', padding: '10px', border: '1px solid #ddd', borderRadius: '5px', fontSize: '14px', boxSizing: 'border-box', outline: 'none', transition: 'border-color 0.2s' },
    fieldError: { color: '#ff4d4f', fontSize: '12px', marginTop: '4px', display: 'block' },
    button: { background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)', color: 'white', border: 'none', padding: '12px', borderRadius: '5px', fontSize: '16px', fontWeight: '500', cursor: 'pointer', marginTop: '10px' },
    links: { marginTop: '20px', textAlign: 'center' },
    link: { color: '#667eea', textDecoration: 'none', fontSize: '14px' }
}

export default Register
